function derivedReady(c:BuildingComponent,raw:readonly BuildingComponent[],leaf:Pin|undefined,owner:Pin|undefined,programReady:boolean,registry:readonly any[]){const p=SPEC.profiles.find(p=>p.partId===c.partId);if(!p||!owner||!nativeReady(raw,leaf,programReady))return false;const reg=registry.find(x=>x.number===p.number),op=c.sourceFeature?.properties?.owner_shape_patch as any;return!!reg&&Object.keys(p).every(k=>JSON.stringify(reg[k])===JSON.stringify((p as any)[k]))&&raw.filter(x=>x.partId===p.partId).length===1&&c.city===p.city&&c.objectId===p.objectId&&JSON.stringify(c.origin)===JSON.stringify(p.origin)&&nativePaintSignature(c)===p.geometrySignature&&owner(c)===p.sha256&&op?.number===p.number&&op?.sourcePartId===p.sourcePartId&&op?.geometryRole===p.geometryRole;}
function allDerivedReady(raw:readonly BuildingComponent[],leaf:Pin|undefined,owner:Pin|undefined,programReady:boolean,registry:readonly any[]){return SPEC.profiles.every(p=>{const c=raw.find(c=>c.partId===p.partId);return!!c&&derivedReady(c,raw,leaf,owner,programReady,registry);});}
export function hnNordlbDisplay1(c:BuildingComponent,raw:readonly BuildingComponent[],leaf:Pin|undefined,owner:Pin|undefined,programReady:boolean,registry:readonly any[]){if(!SPEC.pins.some(p=>p.partId===c.partId&&p.family===20202)&&!SPEC.profiles.some(p=>p.partId===c.partId))return true;const ready=allDerivedReady(raw,leaf,owner,programReady,registry);if(SPEC.pins.some(p=>p.partId===c.partId&&p.family===20202))return!ready;return!SPEC.profiles.some(p=>p.partId===c.partId)||ready;}
export function applyHNNordlb1(draw:BuildingComponent[],colors:Float32Array,frames:Float32Array,raw:readonly BuildingComponent[],leaf:Pin|undefined,owner:Pin|undefined,programReady:boolean,registry:readonly any[]){
 if(!nativeReady(raw,leaf,programReady))return{written:0};const N=draw.reduce((n,c)=>n+c.batches.reduce((a,b)=>a+b.positions.length/3,0),0);if(colors.length!==N*4||frames.length!==N*5)return{written:0};
 const ready=allDerivedReady(raw,leaf,owner,programReady,registry),R=6378137,scale=Math.cos(SPEC.origin[1]*Math.PI/180),circ=2*Math.PI*R*scale,merc=(o:readonly number[])=>[o[0]/360,Math.log(Math.tan(Math.PI/4+o[1]*Math.PI/360))/(2*Math.PI)],mo=merc(SPEC.origin),A=SPEC.plan.axisA,B=SPEC.plan.axisB;let at=0,written=0,nativeWrites=0,derivedWrites=0;
 for(const c of draw){const pin=SPEC.pins.find(p=>key(p)===key(c)),profile=SPEC.profiles.find(p=>p.partId===c.partId),native=!!pin&&!!leaf&&nativePaintSignature(c)===pin.geometrySignature&&leaf(c)===pin.leafSHA256,derived=ready&&!!profile&&derivedReady(c,raw,leaf,owner,programReady,registry);const m=merc(c.origin),dx=(m[0]-mo[0])*circ,dz=(m[1]-mo[1])*circ,ratio=scale/Math.cos(c.origin[1]*Math.PI/180);
  for(const[bi,batch]of c.batches.entries())for(let j=0;j<batch.positions.length/3;j++,at++){
   if(!native&&!derived)continue;const x=batch.positions[j*3]*ratio+dx,z=batch.positions[j*3+2]*ratio+dz,y=batch.positions[j*3+1]*ratio,a=x*A[0]+z*A[1],b=x*B[0]+z*B[1],family=native?pin!.family:profile!.family;
   const cap=native&&batch.normals[j*3+1]>.6,role=native?(cap?2:1):((SPEC.roles as any)[c.partId][bi].role);
   colors[at*4+3]=2;frames.set([a,y,b,role,family],at*5);written++;native?nativeWrites++:derivedWrites++;
  }
 }return{written,nativeWrites,derivedWrites,nativePNIChanged:false,atomicHeightReplacementReady:ready,heldNativeTowerParts:ready?12:0};
}
